ValidationRule.errorConditionFormula:
AND(
    /* Only trigger for Integrated B2B opportunities */
    RecordType.DeveloperName = "Integrated_B2B",

    /* Stage must be one of the restricted values */
    ISPICKVAL(StageName, "Proposal & Negotiation") ||
    ISPICKVAL(StageName, "Implementation/Onboarding") ||
    ISPICKVAL(StageName, "Closed Won"),

    /* Proposal Sent Date is blank */
    ISBLANK(Proposal_Sent_Date__c)
)
